                ->rotation_scalar_98 = -angle;
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->rotation_scalar_94 = 0.0f;
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->special_scalar = 0.0f;
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->lateral_scale = 1.0f;
