                    ->center_x -
                Sin(angle) * Sin(angle * 0.5f) * 2.0f;
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->transform.position.z = (float)(curve_index + 6);
            ((AttachmentSample *)((char *)primary_samples + curve_sample_offset))
                ->transform.position.y = (length - Cos(angle) * length) * 0.40000001f;

