    if (centered)
        ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->center_x = 0.0f;
    else
        ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->center_x = (float)width_cells * 0.5f - 4.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->rotation_scalar_98 = 0.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->rotation_scalar_94 = 0.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->special_scalar = 0.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->lateral_scale = 1.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->transform.Identity();
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->transform.position.x = ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->center_x;
    float last_z = (float)last;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->transform.position.y = 0.0f;
    ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->transform.position.z = last_z;
    ((PathTemplateSample*)((char*)secondary_samples + endpoint_offset))->transform.Identity();
    ((PathTemplateSample*)((char*)secondary_samples + endpoint_offset))->transform.position.x = ((PathTemplateSample*)((char*)primary_samples + endpoint_offset))->center_x;
    ((PathTemplateSample*)((char*)secondary_samples + endpoint_offset))->transform.position.y = 0.49000001f;
    ((PathTemplateSample*)((char*)secondary_samples + endpoint_offset))->transform.position.z = last_z;

    for (int i = 0; i < steps; ++i) {
        int sample_index = i + 1;
        primary_samples[sample_index].center_x = primary_samples[0].center_x;
        primary_samples[sample_index].rotation_scalar_98 = 0.0f;
        primary_samples[sample_index].rotation_scalar_94 = 0.0f;
        primary_samples[sample_index].special_scalar = 0.0f;
        primary_samples[sample_index].lateral_scale = 1.0f;
        float phase = (float)i * 6.2831855f / (float)steps;
        primary_samples[sample_index].transform.Identity();
        primary_samples[sample_index].transform.position.x =
            primary_samples[sample_index].center_x;
        float y = (1.0f - Cos(phase)) * 0.5f;
        y *= height;
        primary_samples[sample_index].transform.position.y = y;
        float z = (float)sample_index;
        primary_samples[sample_index].transform.position.z = z;
        initialize_secondary_hill(this, sample_index, phase, height, z);
        orient_previous_hill_pair(this, sample_index * sizeof(PathTemplateSample));
    }

    compute_path_deltas(this);
    build_strip_mesh(this, texture_a, texture_b);
    CalcLengthZ();
}

